<template>
 <div class="page-stack jobs-page">
  <section class="card workflow-card">
   <div class="section-head"><div><h2>收藏目标岗位</h2><p>把岗位原文留在这里，关联主简历，再开始匹配和准备材料。</p></div></div>
   <p v-if="!auth.isAuthenticated" class="muted-note">请<RouterLink to="/login">登录</RouterLink>后收藏和查看岗位。</p>
   <form v-else data-capture class="capture-form" @submit.prevent="capture">
    <div class="capture-fields"><label><span>岗位名称</span><input v-model="captureForm.title" aria-label="岗位名称" required :disabled="capturing" placeholder="如：平台工程师" /></label><label><span>公司</span><input v-model="captureForm.company" aria-label="公司" :disabled="capturing" placeholder="公司名称（选填）" /></label><label class="source-field"><span>来源链接</span><input v-model="captureForm.sourceUrl" aria-label="来源链接" type="url" :disabled="capturing" placeholder="粘贴招聘页面链接（选填）" /></label></div>
    <label><span>岗位原文</span><textarea v-model="captureForm.text" aria-label="岗位原文" rows="5" required :disabled="capturing" placeholder="粘贴岗位职责、任职要求等原文。收藏后可以解析岗位。" /></label>
    <div class="capture-actions"><button class="button-primary" type="submit" :disabled="capturing || !captureForm.title.trim() || !captureForm.text.trim()">{{ capturing ? '正在收藏…' : '收藏岗位' }}</button><span class="muted-note">重复收藏会打开已有岗位。</span></div>
   </form><p v-if="captureError" class="error-note" role="alert">{{ captureError }}</p><p v-if="notice" role="status" class="save-message">{{ notice }}</p>
  </section>
  <div v-if="auth.isAuthenticated" class="jobs-workspace">
   <section class="card workflow-card jobs-list">
    <div class="section-head"><h2>我的岗位</h2><button class="button-secondary" type="button" :disabled="loading" @click="loadJobs">刷新</button></div>
    <form class="job-filters" @submit.prevent="search"><label><span>搜索岗位</span><input v-model="query" aria-label="搜索岗位" placeholder="岗位或公司" type="search" /></label><label><span>岗位状态</span><select v-model="status" aria-label="岗位状态"><option value="">全部状态</option><option value="saved">已收藏</option><option value="archived">已归档</option></select></label><button class="button-secondary" type="submit" :disabled="loading">搜索</button></form>
    <p v-if="listError" class="error-note" role="alert">{{ listError }}</p><p v-if="loading" role="status">正在加载岗位…</p><p v-else-if="!jobs.length && !listError" class="muted-note">{{ query || status ? '没有符合筛选条件的岗位。试试其他关键词或状态。' : '还没有收藏岗位。粘贴一份岗位原文，开始整理求职目标。' }}</p>
    <ul class="job-links"><li v-for="job in jobs" :key="job.id"><button type="button" :data-job-id="job.id" :aria-current="selectedId === job.id ? 'true' : undefined" @click="openJob(job.id)"><strong>{{ job.title }}</strong><span>{{ job.company || '未填写公司' }}</span><span class="job-tags">{{ job.status === 'archived' ? '已归档' : '已收藏' }} · {{ parseLabel(job.parseStatus) }}</span><time>{{ formatDate(job.capturedAt || job.createdAt) }}</time></button></li></ul>
    <div class="job-pagination"><button class="button-secondary" type="button" :disabled="loading || !offset" @click="changePage(-20)">上一页</button><span>第 {{ offset / 20 + 1 }} 页</span><button class="button-secondary" type="button" :disabled="loading || !hasMore" @click="changePage(20)">下一页</button></div>
   </section>
   <section class="card workflow-card job-detail" aria-label="岗位详情" :aria-busy="detailLoading">
    <p v-if="detailLoading" role="status">正在读取岗位…</p><p v-if="detailError" class="error-note" role="alert">{{ detailError }}</p><button v-if="detailError && !detail" class="button-secondary" type="button" @click="openJob(selectedId!)">重新加载岗位</button>
    <template v-if="detail">
     <div class="section-head"><div><h2>{{ detail.title }}</h2><p>{{ detail.company || '未填写公司' }} · {{ parseLabel(detail.parseStatus) }}</p></div></div>
     <form class="job-edit-form" @submit.prevent="saveDetail"><label><span>编辑岗位名称</span><input v-model="editForm.title" required :disabled="saving" /></label><label><span>编辑公司</span><input v-model="editForm.company" :disabled="saving" /></label><label><span>收藏状态</span><select v-model="editForm.status" aria-label="收藏状态" :disabled="saving"><option value="saved">已收藏</option><option value="archived">已归档</option></select></label><label><span>主简历</span><select v-model="editForm.primaryResumeId" aria-label="主简历" :disabled="saving"><option value="">暂不关联</option><option v-for="resume in documents.parsedResumes" :key="resume.id" :value="String(documentNumber(resume.id))">{{ formatResumeLabel(resume) }}</option></select></label><button class="button-secondary" type="submit" :disabled="saving || !editForm.title.trim()">{{ saving ? '正在保存…' : '保存岗位' }}</button></form>
     <p v-if="documents.error" class="error-note" role="alert">{{ documents.error }}</p><p v-if="detailNotice" class="save-message" role="status">{{ detailNotice }}</p>
     <div class="job-workflow-actions"><button class="button-primary" type="button" :disabled="parsing" @click="startParse">{{ parsing ? '正在解析…' : detail.parseStatus === 'failed' || parseError ? '重试解析' : parsed ? '重新解析岗位' : '解析岗位' }}</button><RouterLink v-if="parsed" class="button-secondary" :to="workflowLink('/matching')">去匹配</RouterLink><RouterLink v-if="parsed" class="button-secondary" :to="workflowLink('/agent/tasks')">准备材料</RouterLink></div><p v-if="!parsed" class="muted-note">解析成功后可以匹配岗位和准备材料。</p><template v-if="parseError"><p class="error-note" role="alert">岗位解析未完成。原文已保留，可以重试解析。</p><details class="parse-error-details"><summary>查看错误详情</summary><p>{{ parseError }}</p></details></template>
     <TaskProgress v-if="task.taskId.value" title="岗位解析进度" :task-id="task.taskId.value" :progress="task.progress.value" :current-step="parseError ? '解析失败' : task.currentStep.value" :completed-count="task.completedSteps.value.length" :steps="task.steps.value" :message="parseError ? '岗位解析未完成，请稍后重试。' : task.message.value" :error-reason="parseError ? '' : task.errorReason.value" />
     <details class="job-source" open><summary>岗位原文</summary><a v-if="safeSourceUrl" :href="safeSourceUrl" target="_blank" rel="noopener noreferrer">查看来源页面</a><p>{{ detail.text }}</p></details>
     <div class="job-history"><h3>历史匹配</h3><p v-if="matchesLoading" role="status">正在读取匹配记录…</p><p v-if="matchesError" class="error-note" role="alert">{{ matchesError }}</p><button v-if="matchesError" class="button-secondary" type="button" @click="loadMatches">重新加载匹配</button><p v-if="!matchesLoading && !matches.length && !matchesError" class="muted-note">尚未匹配这个岗位。解析后选择简历，开始第一次匹配。</p><ul><li v-for="match in matches" :key="`${match.runId}:${match.candidateId}`"><RouterLink :to="matchLink(match)"><strong>{{ Math.round(match.score) }} 分</strong><span>{{ match.resumeId ? `简历 ${match.resumeId}` : '匹配报告' }}</span><time>{{ formatDate(match.createdAt) }}</time><span>查看匹配报告</span></RouterLink></li></ul><button v-if="matchesMore" class="button-secondary" type="button" :disabled="matchesLoading" @click="loadMatches(true)">加载更多匹配</button></div>
    </template><p v-else-if="!detailLoading && !detailError" class="muted-note">选择一个岗位，核对原文、关联简历并查看匹配记录。</p>
   </section>
  </div>
 </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useAuthStore } from '../stores/auth'
import { useDocumentStore } from '../stores/document'
import { captureJob, fetchJob, fetchJobMatches, fetchJobs, parseJob, updateJob, type Job, type JobDetail, type JobMatch } from '../api/jobs'
import { useTaskSse } from '../composables/useTaskSse'
import TaskProgress from '../components/TaskProgress.vue'
import { formatResumeLabel } from '../utils/format'
const auth = useAuthStore(), documents = useDocumentStore(), task = useTaskSse([{ key: 'extract', label: '读取岗位原文' }, { key: 'llm_analyze', label: '分析岗位要求' }, { key: 'milvus_save', label: '保存解析结果' }])
const captureForm = reactive({ title: '', company: '', sourceUrl: '', text: '' }), capturing = ref(false), captureError = ref(''), notice = ref('')
const query = ref(''), status = ref(''), offset = ref(0), jobs = ref<Job[]>([]), hasMore = ref(false), loading = ref(false), listError = ref('')
const selectedId = ref<number | null>(null), detail = ref<JobDetail | null>(null), detailLoading = ref(false), detailError = ref(''), detailNotice = ref(''), saving = ref(false), parsing = ref(false), parseError = ref('')
const editForm = reactive({ title: '', company: '', status: 'saved', primaryResumeId: '' })
const matches = ref<JobMatch[]>([]), matchesMore = ref(false), matchesLoading = ref(false), matchesError = ref('')
let context = 0, listRequest = 0, detailRequest = 0, matchRequest = 0
const parsed = computed(() => ['success', 'success_with_warnings'].includes(detail.value?.parseStatus || ''))
const safeSourceUrl = computed(() => /^https?:\/\//i.test(detail.value?.sourceUrl || '') ? detail.value!.sourceUrl : null)
const documentNumber = (id: string) => Number(id.split(':').pop())
const message = (e: unknown) => e instanceof Error ? e.message : '操作失败，请重试。'
function parseLabel(value: string) { return ({ pending: '待解析', running: '解析中', success: '已解析', success_with_warnings: '已解析（有提示）', failed: '解析失败' } as Record<string, string>)[value] || '待解析' }
function formatDate(value: string | null | undefined) { return value ? new Date(value).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '' }
function workflowLink(path: string) { const params = new URLSearchParams({ jdId: String(detail.value!.id) }); if (detail.value?.primaryResumeId) params.set('resumeId', String(detail.value.primaryResumeId)); return `${path}?${params}` }
function matchLink(match: JobMatch) { return `${workflowLink('/matching')}&matchId=${encodeURIComponent(`${match.runId}:${match.candidateId}`)}` }
async function loadJobs() { const scope = context, mine = ++listRequest; loading.value = true; listError.value = ''; try { const result = await fetchJobs({ query: query.value.trim(), status: status.value, offset: offset.value }); if (scope === context && mine === listRequest) { jobs.value = result.items; hasMore.value = result.hasMore } } catch (e) { if (scope === context && mine === listRequest) listError.value = message(e) } finally { if (scope === context && mine === listRequest) loading.value = false } }
function search() { offset.value = 0; void loadJobs() }
function changePage(amount: number) { offset.value = Math.max(0, offset.value + amount); void loadJobs() }
function setDetail(job: JobDetail) { detail.value = job; Object.assign(editForm, { title: job.title, company: job.company || '', status: job.status, primaryResumeId: job.primaryResumeId ? String(job.primaryResumeId) : '' }) }
async function openJob(id: number) { const scope = context, mine = ++detailRequest; selectedId.value = id; detail.value = null; detailError.value = ''; detailNotice.value = ''; parseError.value = ''; detailLoading.value = true; saving.value = false; parsing.value = false; task.reset(); matches.value = []; matchesMore.value = false; void loadMatches(); try { const job = await fetchJob(id); if (scope === context && mine === detailRequest) setDetail(job) } catch (e) { if (scope === context && mine === detailRequest) detailError.value = message(e) } finally { if (scope === context && mine === detailRequest) detailLoading.value = false } }
async function loadMatches(append: boolean | Event = false) { const scope = context, id = selectedId.value, mine = ++matchRequest; if (!id) return; matchesLoading.value = true; matchesError.value = ''; try { const result = await fetchJobMatches(id, append === true ? matches.value.length : 0); if (scope === context && id === selectedId.value && mine === matchRequest) { matches.value = append === true ? [...matches.value, ...result.items] : result.items; matchesMore.value = result.hasMore } } catch (e) { if (scope === context && id === selectedId.value && mine === matchRequest) matchesError.value = message(e) } finally { if (scope === context && id === selectedId.value && mine === matchRequest) matchesLoading.value = false } }
async function capture() { if (capturing.value) return; const scope = context; capturing.value = true; captureError.value = ''; notice.value = ''; try { const result = await captureJob({ ...captureForm }); if (scope !== context) return; Object.assign(captureForm, { title: '', company: '', sourceUrl: '', text: '' }); notice.value = result.created ? '岗位已收藏。解析后可以开始匹配。' : '已打开之前收藏的岗位。'; offset.value = 0; await Promise.all([loadJobs(), openJob(result.job.id)]) } catch (e) { if (scope === context) captureError.value = message(e) } finally { if (scope === context) capturing.value = false } }
async function saveDetail() { if (!detail.value || saving.value) return; const scope = context, id = detail.value.id, mine = detailRequest; saving.value = true; detailError.value = ''; detailNotice.value = ''; try { const job = await updateJob(id, { ...editForm, primaryResumeId: editForm.primaryResumeId ? Number(editForm.primaryResumeId) : null }); if (scope !== context || mine !== detailRequest) return; setDetail(job); detailNotice.value = '岗位资料已保存。'; await loadJobs() } catch (e) { if (scope === context && mine === detailRequest) detailError.value = message(e) } finally { if (scope === context && mine === detailRequest) saving.value = false } }
async function startParse() { if (!detail.value || parsing.value) return; const scope = context, id = detail.value.id, mine = detailRequest; parsing.value = true; parseError.value = ''; task.reset(); try { await parseJob(id, taskId => { if (scope === context && mine === detailRequest) task.start(taskId) }); const job = await fetchJob(id); if (scope !== context || mine !== detailRequest) return; setDetail(job); await Promise.all([loadJobs(), documents.loadDocuments()]) } catch (e) { if (scope === context && mine === detailRequest) { parseError.value = message(e); task.failManual('岗位解析未完成，请稍后重试。'); try { const current = await fetchJob(id); if (scope === context && mine === detailRequest) { detail.value = current; await loadJobs() } } catch { /* 保留解析失败原因，稍后仍可重新读取岗位。 */ } } } finally { if (scope === context && mine === detailRequest) parsing.value = false } }
watch(status, search)
watch(() => auth.token, () => { context++; listRequest++; detailRequest++; matchRequest++; jobs.value = []; detail.value = null; selectedId.value = null; matches.value = []; captureError.value = ''; listError.value = ''; detailError.value = ''; notice.value = ''; capturing.value = false; loading.value = false; detailLoading.value = false; query.value = ''; status.value = ''; offset.value = 0; Object.assign(captureForm, { title: '', company: '', sourceUrl: '', text: '' }); task.reset(); if (auth.token) { void loadJobs(); void documents.loadDocuments() } }, { immediate: true })
onBeforeUnmount(() => { context++; listRequest++; detailRequest++; matchRequest++ })
</script>
<style scoped>
.jobs-page { overflow-wrap: anywhere; } .capture-form,.capture-form label,.job-filters label,.job-edit-form label { display: grid; gap: 8px; min-width: 0; } .capture-form { gap: 18px; } .capture-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; } .source-field { grid-column: 1/-1; } .capture-form textarea { resize: vertical; min-height: 130px; width: 100%; } .capture-form input,.job-filters input,.job-filters select,.job-edit-form input,.job-edit-form select { width: 100%; min-width: 0; } .capture-actions,.job-workflow-actions { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; } .jobs-workspace { display: grid; grid-template-columns: minmax(280px,.8fr) minmax(0,1.4fr); gap: 24px; align-items: start; } .jobs-list,.job-detail { min-width: 0; } .job-filters { display: grid; gap: 14px; margin-bottom: 22px; } .job-links { padding: 0; list-style: none; display: grid; gap: 12px; } .job-links button { display: grid; gap: 8px; width: 100%; padding: 18px; text-align: left; border: 1px solid var(--color-border); border-radius: var(--radius-sm); background: var(--surface-panel); color: var(--color-text); overflow-wrap: anywhere; } .job-links button[aria-current] { background: var(--color-primary-light); border-color: var(--color-primary-border); } .job-links span,.job-links time { color: var(--color-text-secondary); font-size: 13px; } .job-links strong { font-size: 16px; } .job-pagination { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; margin-top: 24px; font-size: 13px; } .job-edit-form { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1fr); gap: 16px; margin-bottom: 20px; } .job-edit-form button { justify-self: start; } .job-workflow-actions { margin: 24px 0 16px; } .job-workflow-actions a { text-decoration: none; } .parse-error-details { margin: 12px 0; color: var(--color-text-secondary); font-size: 13px; line-height: 1.7; } .parse-error-details summary { cursor: pointer; } .parse-error-details p { white-space: pre-wrap; } .job-source { margin: 24px 0; padding: 20px 0; border-top: 1px solid var(--color-border); border-bottom: 1px solid var(--color-border); } .job-source summary { font-weight: 600; cursor: pointer; margin-bottom: 16px; } .job-source p { white-space: pre-wrap; line-height: 1.8; margin-bottom: 0; } .job-source a { color: var(--color-primary); } .job-history ul { list-style: none; margin: 16px 0; padding: 0; display: grid; gap: 12px; } .job-history a { display: flex; flex-wrap: wrap; gap: 12px; text-decoration: none; padding: 14px; background: var(--surface-panel-muted); border-radius: var(--radius-sm); color: var(--color-text); } .job-history span,.job-history time,.muted-note { font-size: 14px; color: var(--color-text-secondary); line-height: 1.7; } .save-message { color: var(--color-success); } @media(max-width:1000px) { .jobs-workspace { grid-template-columns: 1fr; } } @media(max-width:600px) { .capture-fields,.job-edit-form { grid-template-columns: 1fr; } .section-head { flex-wrap: wrap; gap: 12px; } .job-pagination .button-secondary { padding-inline: 12px; } }
</style>
